import {defaults,valueCompany} from './engine.js';
import {mountSimulation} from './simulation-view.js';
import {enterPanel,reducedMotion} from './motion.js';
import {currentSnapshot,currentIssues,calculateCurrent,safeDraft,quoteComparison,freezeCurrent,waccWorksheet,researchCaseFor,loadResearchedBaseCase,markDraftEdited,fetchBaseCases,currentClaimsEvidence,claimsDefinition,claimsDefaults,claimsSensitivity,currentEconomicShareBasis,operatingProfileDefinition} from './current-model.js';
import {assumptionEvidence,formatEvidenceValue} from './assumption-history.js';
import {renderHistorySeries,renderHistoryCoverage} from './history-view.js';

const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(v,d=1)=>typeof v==='number'&&Number.isFinite(v)?v.toLocaleString('en-US',{maximumFractionDigits:d}):'—';
const pc=v=>Number.isFinite(v)?num(v*100,1)+'%':'—';
const safeURL=u=>/^https?:\/\//.test(u||'')?u:'#';
const groups=[{id:2,name:'Growth'},{id:3,name:'Profitability'},{id:4,name:'Investment'},{id:5,name:'Risk'},{id:6,name:'Equity'},{id:1,name:'Story'},{id:0,name:'Sources'},{id:7,name:'Details'}];
let library,company,raw,snapshot,draft,historyData=null,marketReferences=null,baseCases=null,storageOkay=true;
let releaseSimulation=()=>{},simulationTimer=null,firstMount=true;
const app=$('#guided-app'),sessionDrafts=new Map(),undoBaseCases=new Map();
const key=()=>`valuation-lab-guided-v5:${company.ticker}:${raw?.id}`;
function store(){
 draft.updatedAt=new Date().toISOString();sessionDrafts.set(key(),JSON.stringify(draft));
 try{localStorage.setItem(key(),JSON.stringify(draft));localStorage.setItem('valuation-lab-guided-selection',JSON.stringify({ticker:company.ticker,id:raw?.id}));}catch{storageOkay=false}
 const state=$('#base-case-state');if(state)state.textContent=researchState();
 const el=$('#guided-save-state');if(el)el.textContent=storageOkay?'Saved on this device':'Storage unavailable · export before leaving';
}
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function choose(ticker,id){
 company=library.companies.find(c=>c.ticker===ticker)||library.companies[0];
 raw=company.snapshots?.find(s=>s.id===id)||company.snapshots?.find(s=>s.id===company.currentSnapshotId)||company.snapshots?.find(s=>['ttm','annual-reference'].includes(s.snapshotMode))||company.snapshots?.[0]||{};
 snapshot=currentSnapshot(company,raw);let saved;try{saved=JSON.parse(sessionDrafts.get(key())||localStorage.getItem(key())||'null')}catch{}
 draft=safeDraft(saved,company,raw,{baseCases});firstMount=true;store();render();
}
function table(head,rows){return `<div class="table-wrap"><table><thead><tr>${head.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>'<tr>'+r.map(v=>`<td>${v}</td>`).join('')+'</tr>').join('')}</tbody></table></div>`}
function evidenceFor(k){try{return assumptionEvidence(historyData,company.ticker,k,{snapshot,marketReferences,cutoff:draft.cutoff})}catch{return {title:'Company history',series:[],summary:'Verified historical comparison is unavailable for this field.',cautions:[],status:'unavailable'}}}
function historyValue(v,e){try{return formatEvidenceValue(v,e.unit)}catch{return num(v,2)}}
function historySeries(series,unit,title){return renderHistorySeries(series,unit,title)}
const researchLabels={growth:'Initial revenue growth',targetMargin:'Mature operating margin',tax:'Cash tax rate',salesCapital:'Incremental sales / capital',wacc:'Cost of capital',terminalGrowth:'Stable growth',terminalROIC:'Mature marginal ROIC',otherAssets:'Other assets',otherClaims:'Other claims'};
const researchUnit=k=>k==='salesCapital'?'multiple':['otherAssets','otherClaims','normalizationDelta'].includes(k)?snapshot.currency+' millions':'percent';
function researchRationale(k){const c=researchCaseFor(baseCases,company,raw),reason=c?.rationale?.[k]||(k==='normalizationDelta'?c?.normalization?.adjustmentReason:null);if(!reason)return '';const value=k==='normalizationDelta'?c.normalization?.normalizationDelta:c.assumptions[k];return `<details class="driver-rationale"><summary>${c.displayLabel?'Assumption reasoning':'Base-case reasoning'} <span>${esc(formatEvidenceValue(value,researchUnit(k)))}${['otherAssets','otherClaims','normalizationDelta'].includes(k)?'m':''}</span></summary><p>${esc(reason)}</p><p class="micro">Research judgment as of ${esc(c.asOf||baseCases.asOf)}. Your input stays editable; the source history below is a separate reference.</p></details>`;}
function researchState(){if(company.ticker==='AAOI'&&raw.id==='AAOI-TTM-2026-06-30'&&draft.operatingProfile?.id!=='aaoi-capacity-ramp-v1')return 'Saved / generic linear path · staged research available';const p=draft.assumptionProvenance,c=researchCaseFor(baseCases,company,raw);return p?.kind==='researched-base-case'?(p.userEdited?'Your edits · based on researched assumptions':(c?.displayLabel||'Researched base case')+' · '+(p.asOf||'dated')):p?.kind==='user-draft'?'Saved inputs kept · research case ready':'Generic inputs · research case ready';}
function normalizationBanner(){if(!Number.isFinite(draft.normalizationDelta)||draft.normalizationDelta===0)return '';const margin=(snapshot.ebit+draft.normalizationDelta)/snapshot.revenue;return `<div class="base-normalization applied-normalization"><b>Starting EBIT adjusted by ${num(draft.normalizationDelta)}m ${esc(snapshot.currency)}</b><p>Model starting margin: ${pc(margin)}. This is an analyst adjustment; reported EBIT remains unchanged.</p>${draft.adjustmentSource?`<a href="${esc(safeURL(draft.adjustmentSource))}" target="_blank" rel="noopener">Adjustment source ↗</a>`:''}</div>`;}
function baseCasePanel(){
 const c=researchCaseFor(baseCases,company,raw);if(!c)return normalizationBanner()+`<p class="base-case-fallback">${draft.assumptionProvenance?.kind==='generic-default'&&!draft.assumptionProvenance?.userEdited?'Generic fallback assumptions':'Saved inputs retained'} · no researched case is available for this exact baseline.</p>`;
 const sources=(c.sourceIds||[]).map(id=>Array.isArray(baseCases.sources)?baseCases.sources.find(s=>s.id===id):baseCases.sources?.[id]).filter(Boolean);
 const status=researchState();
 return `<div class="base-case-control">${normalizationBanner()}${(c.economicChecks?.negativeFCFFYears||[]).length>=5?`<p class="base-case-warning">${esc(c.displayLabel||'Research case')}: negative FCFF in ${c.economicChecks.negativeFCFFYears.length} of 10 forecast years. This simple model does not model the funding needed to sustain that cash burn.</p>`:c.economicChecks?.terminalValueShareOfOperatingEV>.75?`<p class="base-case-warning">Research case: terminal value supplies ${pc(c.economicChecks.terminalValueShareOfOperatingEV)} of operating value, so the mature-growth and return assumptions have an outsized effect.</p>`:''}<div class="base-case-bar"><span id="base-case-state">${esc(status)}</span><button id="load-base-case" class="quiet">${c.displayLabel?'Use research assumptions':'Use researched base case'}</button>${undoBaseCases.has(key())?'<button id="undo-base-case" class="text-button">Undo load</button>':''}</div><p id="base-case-action-status" role="status" class="micro"></p><details id="base-case-panel" class="base-case-panel"><summary><span>Why these inputs? · ${esc(company.ticker)}</span><small>Research case & sources</small></summary><p>${esc(c.summary)}</p><p class="micro">Dated ${esc(c.asOf||baseCases.asOf)}. These are analyst judgments, not reported facts, fitted probabilities or investment advice. Loading replaces the model assumptions, stated starting-profit normalization and any named company-specific operating profile. Your notes and quote are retained.</p>${c.normalization?.normalizationDelta?`<div class="base-normalization"><b>Starting operating-profit adjustment: ${esc(formatEvidenceValue(c.normalization.normalizationDelta,snapshot.currency+' millions'))}m ${esc(snapshot.currency)}</b><p>${esc(c.normalization.adjustmentReason)}</p><a href="${esc(safeURL(c.normalization.adjustmentSource))}" target="_blank" rel="noopener">Adjustment source ↗</a></div>`:''}<div class="base-case-comparison">${Object.entries(researchLabels).map(([k,label])=>`<article class="base-case-driver"><div class="base-case-driver-top"><span>${label}</span><strong>${esc(formatEvidenceValue(c.assumptions[k],researchUnit(k)))}${['otherAssets','otherClaims'].includes(k)?'m':''}</strong></div><small class="base-case-current">Current: ${esc(formatEvidenceValue(draft.assumptions[k],researchUnit(k)))}${['otherAssets','otherClaims'].includes(k)?'m':''}</small>${c.rationale?.[k]?`<p>${esc(c.rationale[k])}</p>`:''}</article>`).join('')}</div>${c.reportedAnchors?.length?`<h3>Reported reference points</h3><ul>${c.reportedAnchors.map(a=>`<li>${esc(a.text||`${a.periodEnd}: revenue ${num(a.revenue)}m ${a.currency}; reported operating margin ${pc(a.operatingMargin)}.`)}</li>`).join('')}</ul>`:''}${c.economicChecks?`<h3>What the research case implies</h3><p>Year 10 revenue: ${num(c.economicChecks.revenueMultiple10Years,1)}× the starting level. Negative FCFF: ${(c.economicChecks.negativeFCFFYears||[]).length} of 10 years. ${Number.isFinite(c.economicChecks.terminalValueShareOfOperatingEV)?`Terminal value supplies ${pc(c.economicChecks.terminalValueShareOfOperatingEV)} of operating value.`:'Terminal-value share is not meaningful when operating value is nonpositive.'} These are computed consequences of the proposed assumptions.</p>`:''}${c.bridgePolicy?`<h3>Claims and model limits</h3><p>${esc(typeof c.bridgePolicy==='string'?c.bridgePolicy:c.bridgePolicy.note||'Claims remain unreviewed.')}</p>`:''}${Array.isArray(c.modelLimits)?`<ul>${c.modelLimits.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:typeof c.modelLimits==='string'?`<p>${esc(c.modelLimits)}</p>`:''}${c.uncertainties?.length?`<h3>What could change this case</h3><ul>${c.uncertainties.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}${sources.length?`<ul class="base-case-sources">${sources.map(s=>`<li><a href="${esc(safeURL(s.url||s.sourceUrl||s.href))}" target="_blank" rel="noopener">${esc(s.title||s.label||s.id||'Primary source')} ↗</a></li>`).join('')}</ul>`:''}<a class="base-case-ledger" href="./data/company-base-cases.json" target="_blank" rel="noopener">Complete case and source ledger ↗</a></details></div>`;
}
function bindBaseCase(){
 const load=$('#load-base-case');if(load)load.onclick=()=>{try{const prior=structuredClone(draft);draft=loadResearchedBaseCase(draft,company,raw,baseCases);undoBaseCases.set(key(),prior);store();render();$('#base-case-panel').open=true;$('#base-case-action-status').textContent='Research assumptions loaded. You can undo this change.';}catch(e){$('#base-case-action-status').textContent=e.message}};
 const undo=$('#undo-base-case');if(undo)undo.onclick=()=>{const previous=undoBaseCases.get(key());if(!previous)return;draft=structuredClone(previous);undoBaseCases.delete(key());store();render();$('#base-case-panel').open=true;$('#base-case-action-status').textContent='Your previous draft has been restored.';};
}
function historyPanel(k){
 const e=evidenceFor(k),series=e.series||[],sources=e.sources||[],context=e.contextSeries||[],components=e.components||[];
 const contextBlock=g=>`<div class="history-context"><div class="history-context-title">${esc(g.title)}${g.unit&&!['percent','multiple','x'].includes(g.unit)?` · ${esc(g.unit)}`:''}</div>${historySeries(g.series||[],g.unit,g.title)}</div>`;
 return `<div class="assumption-history" data-history="${k}"><div class="history-heading"><span>${esc(e.title||'Company history')}</span><span class="history-status">${e.kind==='proxy'?'Historical proxy':series.length?'Annual history':'Evidence context'}</span></div>${renderHistoryCoverage(e.coverage)}${series.length?historySeries(series,e.unit,e.title):''}${components.length?`<div class="history-components">${components.map(p=>`<a href="${esc(safeURL(p.sourceUrl))}" target="_blank" rel="noopener"><span>${esc(p.label)}<small>${esc(p.date)}${p.currency?' · '+esc(p.currency):''}</small></span><b>${esc(historyValue(p.value,{unit:p.unit}))}</b></a>`).join('')}</div>`:''}${e.ttm?`<div class="history-ttm"><span>${esc(e.ttm.period)} · separate from FY range</span><b>${esc(historyValue(e.ttm.value,e))}</b></div>`:''}<p class="history-summary">${esc(e.summary||'No verified comparable history in the saved source library.')}</p>${e.range?`<p class="history-range">${esc(e.range.label||'Observed range')} <b>${esc(historyValue(e.range.min,e))}–${esc(historyValue(e.range.max,e))}</b>${Number.isFinite(e.range.median)?` · median ${esc(historyValue(e.range.median,e))}`:''}</p>`:''}${context.slice(0,series.length?1:2).map(contextBlock).join('')}<details class="history-method"><summary>Sources & comparability <span aria-hidden="true">↗</span></summary>${context.slice(series.length?1:2).map(contextBlock).join('')}${e.formula?`<p>${esc(e.formula)}</p>`:''}${(e.cautions||[]).map(c=>`<p>${esc(c)}</p>`).join('')}${series.filter(p=>!Number.isFinite(p.value)).map(p=>`<p><b>${esc(p.period)} unavailable:</b> ${esc(p.detail||'No verified comparable observation.')}</p>`).join('')}${sources.length?`<ul>${sources.map(s=>`<li><a href="${esc(safeURL(typeof s==='string'?s:s.url||s.sourceUrl||s.sourceURL))}" target="_blank" rel="noopener">${esc(typeof s==='string'?'Original source':s.label||s.title||s.period||'Original source')} ↗</a></li>`).join('')}</ul>`:'<p>Missing evidence is not zero. No historical value is inferred from your assumption.</p>'}</details></div>`;
}
function field(k,label,help,scale=100,unit='%',min=0,max=100,step=.5){
 const value=Number.isFinite(draft.assumptions[k])?Math.round(draft.assumptions[k]*scale*1e6)/1e6:'';
 const unitDescription=unit==='%'?'Percent':unit==='×'?'Times':unit==='m'?`${snapshot.currency} millions`:unit;
 return `<article class="driver-card${unit==='m'?' driver-card--amount':''}"><div class="driver-top"><label for="g-${k}">${label}<span class="assumption-tag">Your assumption</span></label><div class="driver-number"><input id="g-${k}" type="number" inputmode="decimal" data-assumption="${k}" data-scale="${scale}" value="${value}" min="${min}" max="${max}" step="${step}" aria-describedby="g-hint-${k}"><span>${unit}</span></div></div><input class="driver-range" type="range" data-slider="${k}" data-scale="${scale}" value="${value}" min="${min}" max="${max}" step="${step}" aria-label="${esc(label)}" aria-describedby="g-hint-${k}"><p class="driver-help" id="g-hint-${k}"><span class="sr-only">${esc(unitDescription)}. </span>${help}</p>${researchRationale(k)}${historyPanel(k)}</article>`;
}
function note(k,label,placeholder='What evidence supports this? What would change your mind?'){return `<details class="research-note"><summary>${label} <span>Optional note</span></summary><label class="sr-only" for="note-${k}">${label}</label><textarea id="note-${k}" data-note="${k}" placeholder="${esc(placeholder)}">${esc(draft.notes[k]||'')}</textarea></details>`}
function sourceEvidence(){
 const fields=[['Revenue',snapshot.revenue],['Operating profit',snapshot.ebit],['Cash & securities',snapshot.cash],['Mapped debt',snapshot.debt],['Shares · millions',snapshot.shares],['Operating margin',snapshot.ebit/snapshot.revenue]];
 return `<div class="source-facts">${fields.map(([label,v],i)=>`<div><span>${label}</span><b>${i===5?pc(v):num(v)}</b></div>`).join('')}</div><p class="micro">Amounts in ${esc(snapshot.currency)} millions except margin. ${esc(raw.derivation||'Reported filing inputs; no automatic accounting normalization.')}</p><a href="${esc(safeURL(snapshot.sourceUrl))}" target="_blank" rel="noopener">Open original filing ↗</a><details><summary>Field-level evidence ledger</summary>${table(['Field','Value','Evidence'],Object.entries(raw.facts||{}).map(([k,v])=>[esc(k),num(v),v===null?'Missing':raw.factEvidence?.[k]?.formula||raw.factEvidence?.[k]?.derivation?'Derived from filing components':raw.factEvidence?.[k]?.originalInlineVerified||raw.factEvidence?.[k]?.originalDocumentVerified?'Original filing verified':'Source-linked']))}<a href="./data/current-universe.json" target="_blank" rel="noopener">Complete source ledger ↗</a></details><p class="design-notebook-link"><a href="./data/design-notebook.html">Design notebook & change log ↗</a></p>`;
}
function worksheet(){return `<details class="wacc-worksheet"><summary>Build WACC from its components <span>Optional worksheet</span></summary><p class="micro">Complete all seven inputs to use the calculated WACC automatically. Editing WACC directly switches back to your scalar assumption. No market reference is inserted automatically.</p><div class="worksheet-grid">${[['riskFree','Risk-free rate',100,'%'],['beta','Levered equity beta',1,'×'],['equityPremium','Equity risk premium',100,'%'],['countryPremium','Country-risk premium',100,'%'],['costOfDebt','Pretax cost of debt',100,'%'],['debtWeight','Debt / market capital',100,'%'],['tax','Marginal tax rate',100,'%']].map(([k,label,scale,u])=>`<label for="wacc-${k}">${label} · ${u}<input id="wacc-${k}" data-wacc="${k}" data-scale="${scale}" type="number" inputmode="decimal" step=".1" min="0" value="${Number.isFinite(draft.waccWorksheet?.[k])?draft.waccWorksheet[k]*scale:''}"></label>`).join('')}</div><p id="wacc-output" class="micro" role="status"></p></details>`}
function operatingProfilePanel(){if(company.ticker!=='AAOI'||raw.id!=='AAOI-TTM-2026-06-30'||!claimsDefinition(snapshot))return '';const staged=draft.operatingProfile?.id==='aaoi-capacity-ramp-v1';return `<section class="operating-profile-panel"><label for="operating-profile">Operating path<select id="operating-profile"><option value="aaoi-capacity-ramp-v1" ${staged?'selected':''}>Staged capacity research case</option><option value="linear-v1" ${!staged?'selected':''}>Legacy linear path · operating stress</option></select></label><p>${staged?'Front-loaded growth, staged profitability, and initial sales/capital that improves with utilization before fading to terminal-consistent capital intensity. The same path shapes every simulated draw.':'Your existing linear-path inputs are preserved. This slow margin transition can produce severe cash burn; it is an operating stress, not a validated fair-value case.'}</p><a href="./data/current-claims-research.json" target="_blank" rel="noopener">Path assumptions & source evidence ↗</a></section>`}
function refreshQuoteBasis(){const el=$('#quote-share-basis');if(!el)return;const basis=currentEconomicShareBasis(snapshot,draft),saved=draft.quote.shareBasis;el.innerHTML=`<option value="">Choose the quote’s actual share basis</option><option value="${esc(basis)}" ${saved===basis?'selected':''}>${esc(basis)}</option>${saved&&saved!==basis&&saved!=='unmatched'?`<option value="${esc(saved)}" selected>Previously saved basis · review after capital change</option>`:''}<option value="unmatched" ${saved==='unmatched'?'selected':''}>Different or unverified security / split basis</option>`;el.value=saved||'';}
function claimsField(key,label,help,{scale=1,step=1,min=0,max}={}){const v=draft.claims?.[key];return `<label class="claims-input" for="claim-${key}">${label}<input id="claim-${key}" data-claim="${key}" data-scale="${scale}" type="number" inputmode="decimal" step="${step}" ${min===null?'':`min="${min}"`} ${max===undefined?'':`max="${max}"`} value="${Number.isFinite(v)?numPlain(v*scale):''}"><small>${help}</small></label>`}
function numPlain(v){return Number.isFinite(v)?String(Math.round(v*1e8)/1e8):''}
function claimsSelect(key,label,options){const v=draft.claims?.[key];return `<label class="claims-input" for="claim-${key}">${label}<select id="claim-${key}" data-claim-select="${key}">${!options.some(([id])=>id===v)?'<option value="">Choose a valid treatment</option>':''}${options.map(([id,text])=>`<option value="${id}" ${id===v?'selected':''}>${text}</option>`).join('')}</select></label>`}
function claimsPanel(){
 const d=claimsDefinition(snapshot);if(!d)return '';
 const c=draft.claims||{},isAAOI=d.type==='convertible';
 const inputs=isAAOI?claimsSelect('method','Convertible-note treatment',[['fair-value','Disclosed fair-value claim'],['principal-only','Principal only · omits option'],['if-converted','Immediate full-share conversion']])+claimsSelect('capitalBasis','Capital reference',[['reported',`${d.periodEnd} reported capital`],...(d.knownTransactions?[['known-transactions','Known ATM pro forma · cash bridge incomplete']]:[])])+claimsField('noteFairValue','Convertible value proxy · USD millions','Used only for fair-value treatment. The disclosed mark includes the conversion option; no note shares are added.',{step:.1})+claimsField('vendorFinancingFraction','Vendor financing included · %','100% follows the financing cash-flow classification. A lower percentage is a stress assumption; reinvestment must be before vendor financing.',{scale:100,step:5,max:100})+claimsSelect('warrantCoverage','Customer-warrant count',[['all','All 7.945399m · assume future vesting'],['initially-vested','1.324233m initially vested · incomplete count']])+claimsField('warrantTimeValueReserve','Additional warrant time-value reserve · USD millions','The intrinsic calculation does not capture time value. Zero leaves that liability unmodeled; it does not mean the options are worthless.',{step:1})+(d.knownTransactions?claimsField('interimCashChange','Unknown interim cash change · USD millions','Only used in the ATM pro forma, after the separately deducted $26.783472m property purchase. Zero is an assumption for all remaining cash changes. Enter cash burn as negative; this is not a verified current cash balance.',{step:10,min:null}):'')
 : claimsSelect('method','Preferred-stock treatment',[['if-converted','Full-dilution proxy + cash dividend PV'],['liquidation-proxy','Liquidation priority proxy · not fair value']])+claimsSelect('conversionCase','Contractual conversion endpoint',[['maximum','Maximum · 54.45825m common shares'],['minimum','Minimum · 43.56275m common shares']])+claimsField('dividendDiscountRate','Preferred dividend discount rate · %','Independent analyst discount assumption. Future cash dividends are valued from June 30, not the later research cutoff. Conversion mode only.',{scale:100,step:.25,max:100})+claimsField('noncontrollingClaim','Noncontrolling-interest value proxy · USD millions','Reported $7,100m includes $824m redeemable NCI. Carrying amount is a proxy, not a market value.',{step:100})+claimsField('noncurrentInvestmentValue','Gross noncurrent investments proxy · USD millions','$14,126m marketable equity + $131,461m nonmarketable investments. Carrying-value starting point; no realization-tax adjustment.',{step:1000})+claimsField('currentEquityHaircut','Current marketable-equity haircut · %','Applied only to $87,063m already in cash/marketables, including $80,000m restricted equity. It is not added a second time.',{scale:100,step:5,max:100});
 return `<section class="claims-panel" aria-label="Explicit source-dated claims model"><div class="claims-heading"><span class="eyebrow">SOURCE-DATED CLAIMS</span><h3>${isAAOI?'Convertibles, financing & warrants':'Preferred stock & nonoperating claims'}</h3><p>${esc(d.description)}</p></div><p class="claims-date">Capital reference: ${esc(d.periodEnd)} · USD millions; shares in millions. Existing saved operating inputs are retained.</p><div class="claims-input-grid">${inputs}</div><button id="reset-claims" class="quiet">Reset source-dated claims assumptions</button><p class="micro">Other claims/assets below are additional to this model. Do not enter these convertible, preferred, financing, investment or NCI amounts again.</p><div id="claims-calculation"></div><details><summary>Assumptions, approximations & sources</summary><ul>${d.cautions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${d.knownTransactions?'<p>The October 5 ATM raised $588.0m net and issued 5.694845m common shares. Reported June capital excludes that event. The optional pro forma uses August 20 common shares plus this issuance, and deducts the known $26.783472m September property cash purchase. All other intervening cash changes need your own adjustment.</p>':''}<ul>${d.sources.map(x=>`<li><a href="${esc(safeURL(x.url))}" target="_blank" rel="noopener">${esc(x.title)} ↗</a></li>`).join('')}</ul><a href="./data/current-claims-research.json" target="_blank" rel="noopener">Claims research and assumptions ledger ↗</a></details></section>`;
}
function refreshClaimsCalculation(v){
 const el=$('#claims-calculation');if(!el)return;if(!v?.claimsBridge){el.innerHTML='<p class="error">Correct the claims inputs to see the bridge.</p>';return}
 const b=v.claimsBridge,d=claimsDefinition(snapshot),cashLabel=d.type==='mandatory-preferred'?'Cash + mapped marketables (includes restricted equity)':'Cash reference / chosen pro forma';
 el.innerHTML=`<h4>Enterprise to common equity</h4>${table(['Bridge item','USD millions'],[['Operating enterprise value',num(v.enterprise,2)],[cashLabel,'+ '+num(b.cash,2)],['Additional nonoperating assets','+ '+num(draft.assumptions.otherAssets,2)],['Mapped borrowing debt','− '+num(b.mappedDebt,2)],['Additional other claims','− '+num(draft.assumptions.otherClaims,2)],...b.rows.filter(x=>x.kind!=='shares'&&!['ATM net proceeds','Assumed interim cash change','Known September property cash use'].includes(x.label)).map(x=>[esc(x.label),(x.kind==='asset'?'+ ':'− ')+num(x.amount,2)]),['Common equity before the zero floor',num(v.equity,2)]])}<p class="micro">Allocation denominator: ${num(b.allocationShares,6)}m common shares. ${b.warrantClaim>0?`Customer warrants are charged once as an intrinsic claim; equivalent exercise adds ${num(b.exerciseShares,6)}m shares and ${num(b.exerciseCash,2)}m cash, not a second deduction.`:''}</p>${table(['Share allocation','Million common shares'],[['Basic shares · selected dated capital basis',num(b.basicShares,6)],...b.rows.filter(x=>x.kind==='shares').map(x=>[esc(x.label),'+ '+num(x.amount,6)]),['Allocation denominator',num(b.allocationShares,6)]])}<h4>Claims-only sensitivities</h4>${table(['Treatment · same operating assumptions','USD / share','Raw before floor'],claimsSensitivity(snapshot,draft).map(x=>[esc(x.label),x.error?'Unavailable':num(x.perShare,2),x.error?'—':num(x.rawPerShare,2)]))}<p class="micro">Alternatives are conditional comparisons, not estimated probabilities or bounds on fair value.</p>${b.dividends.length?`<details><summary>Preferred dividend schedule · ${num(b.dividends.reduce((s,x)=>s+x.presentValue,0),2)}m present value</summary><p class="micro">Assumes cash dividends through May 2029, no separate pre-conversion common distributions or capped-call recovery, and no change in common shares. Nominal 15th payment dates approximate business-day shifts. First dividend uses the reported $12.15 declaration per preferred share; discounting uses actual days / 365.25.</p>${table(['Scheduled date','Cash · USD m','PV · USD m'],b.dividends.map(x=>[x.date,num(x.amount,4),num(x.presentValue,4)]))}</details>`:''}`;
}
function editorBody(){switch(draft.step){
 case 0:return `<div class="editor-intro"><h2 id="guided-step-title" tabindex="-1">Start with the evidence.</h2><p>Every source stays dated. Current financials never enter the historical experiments.</p></div><label for="g-cutoff">Valuation date · UTC</label><input id="g-cutoff" type="date" value="${esc(draft.cutoff)}">${sourceEvidence()}<div class="model-boundary"><b>Model boundaries</b><p>Simplified nominal operating-company FCFF. Replacement capex, capital lead times, NOLs, financing, R&D/lease restatements and equity-award valuation are not separately modeled.</p></div>${(raw.reviewRequired||[]).length?`<details><summary>Unresolved source questions · ${raw.reviewRequired.length}</summary><ul>${raw.reviewRequired.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:''}`;
 case 1:return `<div class="editor-intro"><h2 id="guided-step-title" tabindex="-1">What makes this business work?</h2><p>A useful model begins with a testable story.</p></div>${note('today','Who pays, and for what?','Customers, products, segments, pricing and the economic engine…')}${note('change','What changes, and why?','Growth drivers, competitive advantage and the next evidence to watch…')}${note('break','What could break the story?','Name one or two falsifiable milestones.') }<details><summary>Normalize starting operating profit</summary><p class="micro">A net EBIT adjustment is not a substitute for coherent R&D, lease, reinvestment or stock-compensation restatement.</p><label for="g-normalize">Net EBIT adjustment · ${esc(snapshot.currency)} millions</label><input id="g-normalize" type="number" inputmode="decimal" value="${draft.normalizationDelta}" step="1">${researchRationale('normalizationDelta')}${historyPanel('normalizationDelta')}<label for="g-adjust-reason">Economic reason</label><textarea id="g-adjust-reason">${esc(draft.adjustmentReason)}</textarea><label for="g-adjust-source">Supporting source URL</label><input id="g-adjust-source" type="url" value="${esc(draft.adjustmentSource)}"><p class="micro">A nonzero adjustment requires both a reason and a source.</p></details>`;
 case 2:return `<div class="editor-intro"><h2 id="guided-step-title" tabindex="-1">How far can it grow?</h2><p>Start with the company's track record. Make your own forward-looking case.</p></div>${field('growth','Initial revenue growth',draft.operatingProfile?.id==='aaoi-capacity-ramp-v1'?'Year 1 of the staged capacity profile; later growth follows documented weights toward the stable rate.':'Fades toward stable growth over a ten-year forecast.',100,'%',-30,100,.5)}<div id="growth-scale" class="economic-insight"></div>${note('growth','Explain your growth story','Customers × spending, price versus volume, capacity and market share…')}`;
 case 3:return `<div class="editor-intro"><h2 id="guided-step-title" tabindex="-1">How much turns into profit?</h2><p>Operating margin and cash taxes determine earnings before reinvestment.</p></div>${field('targetMargin','Mature operating margin',draft.operatingProfile?.id==='aaoi-capacity-ramp-v1'?'GAAP EBIT margin reached in year 6 through the staged operating profile. The same progression applies in every simulation.':'EBIT ÷ revenue, not gross or EBITDA margin. Fades from the normalized starting margin.',100,'%',0,70,.5)}${field('tax','Cash tax rate','Applied only to positive EBIT. No automatic tax credit on losses or NOL ledger.',100,'%',0,60,.5)}${note('profit','Explain margins & taxes')}`;
 case 4:return `<div class="editor-intro"><h2 id="guided-step-title" tabindex="-1">What will growth cost?</h2><p>Growth creates value only when it earns enough on the capital it consumes.</p></div>${field('salesCapital',draft.operatingProfile?.id==='aaoi-capacity-ramp-v1'?'Initial incremental sales / capital':'Incremental sales / capital',draft.operatingProfile?.id==='aaoi-capacity-ramp-v1'?'Initial productivity doubles by years 6–7, then capital intensity fades to match terminal margin, tax, growth and ROIC. Higher initial productivity reduces buildout investment.':'Extra annual revenue per dollar of new invested capital. Higher means less reinvestment.',1,'×',.1,15,.1)}<div class="economic-insight">${draft.operatingProfile?.id==='aaoi-capacity-ramp-v1'?'Initially, each':'Each'} $1 of extra sales requires <b id="capital-per-dollar">${num(1/draft.assumptions.salesCapital,2)}</b> of new capital.</div><details><summary>Where this simplification can fail</summary><p>Maintenance replacement, asset lives, construction lead times and financing are not modeled separately. Declining revenue does not automatically release capital.</p></details>${note('investment','Explain capacity & capital needs')}`;
 case 5:return `<div class="editor-intro"><h2 id="guided-step-title" tabindex="-1">What does the long run look like?</h2><p>Keep risk, currency and the economics of mature growth consistent.</p></div>${field('wacc','Cost of capital · WACC','Nominal discount rate in the cash-flow currency. An assumption, not a live market estimate.',100,'%',1,30,.25)}${worksheet()}${field('terminalGrowth','Stable growth','Must remain below WACC and mature marginal ROIC.',100,'%',0,5,.25)}${field('terminalROIC','Mature marginal ROIC','Return on new capital in maturity. Historical average returns are only context.',100,'%',1,50,.5)}<div class="economic-insight">Stable growth reinvests <b id="stable-reinvestment">${pc(draft.assumptions.terminalGrowth/draft.assumptions.terminalROIC)}</b> of after-tax operating earnings.</div>${note('risk','Explain risk & competitive durability')}`;
 case 6:return `<div class="editor-intro"><h2 id="guided-step-title" tabindex="-1">What belongs to common shareholders?</h2><p>Operating value becomes equity only after accounting for assets and other claims.</p></div>${claimsPanel()}${field('otherAssets','Other nonoperating assets','Only assets excluded from operating cash flows. Amounts in source-currency millions.',1,'m',0,100000,100)}${field('otherClaims','Other claims on equity',claimsDefinition(snapshot)?'Only claims not already included in the explicit model above. Count every claim once.':'Additional debt, minority/preferred interests, awards or obligations, counted once.',1,'m',0,100000,100)}${table(['Source bridge item',`${esc(snapshot.currency)} millions`],[[company.ticker==='GOOG'?'Captured cash + current marketables (includes equity)':'Captured cash & mapped securities',num(snapshot.cash)],['Mapped debt',num(snapshot.debt)],[claimsDefinition(snapshot)?'Captured cover-date shares (bridge uses dated basis above)':'Common shares',num(snapshot.shares,2)]])}<p class="micro">${esc(claimsDefinition(snapshot)&&company.ticker==='GOOG'?'The capture includes current marketable equity; the source-specific bridge above supplies the corrected definition.':raw.cashDefinition||'Cash restrictions require judgment.')} ${esc(raw.debtDefinition||'Review mapped debt and leases.')} ${esc(snapshot.shareBasis)}; dated ${esc(snapshot.coverShareDate||'unverified')}.</p><details><summary>Open accounting questions</summary><ul>${[...new Set([...(raw.reviewRequired||[]),...(raw.valuationBlockers||[])])].map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>Zero extra claims is an illustrative assumption. It is not evidence that no claims exist.</p></details>${note('claims','Explain your claims treatment')}`;
 case 7:return `<div class="editor-intro"><h2 id="guided-step-title" tabindex="-1">Follow every dollar.</h2><p>Cash-flow arithmetic and scenarios for the current assumptions.</p></div><div id="forecast-detail"></div>${note('challenge','What new evidence would change your mind?')}<button id="freeze-current" class="primary">Export this valuation ↓</button><p id="freeze-status" class="micro" role="status"></p><details><summary>Method & limitations</summary><p>Original educational synthesis of Aswath Damodaran’s public framework. No affiliation or endorsement. Conditional values are not target prices, investment advice or calibrated probabilities.</p><a href="https://pages.stern.nyu.edu/~adamodar/New_Home_Page/webcastvalonline.htm" target="_blank" rel="noopener">Official valuation class ↗</a></details>`;
}}
function quoteForm(){return `<details id="market-quote" class="quote-details"><summary>Compare a market price <span>No live feed</span></summary><p class="micro">Use a dated quote with the same currency and economic security. A quote does not change the valuation.</p><div class="quote-grid"><label for="quote-price">Price / share<input id="quote-price" data-quote="price" type="number" inputmode="decimal" min=".0001" step=".01" value="${esc(draft.quote.price??'')}"></label><label for="quote-date">Quote date<input id="quote-date" data-quote="date" type="date" value="${esc(draft.quote.date)}"></label><label for="quote-currency">Currency<input id="quote-currency" data-quote="currency" type="text" maxlength="3" value="${esc(draft.quote.currency)}" placeholder="${esc(snapshot.currency)}"></label><label for="quote-source">Source URL<input id="quote-source" data-quote="sourceUrl" type="url" value="${esc(draft.quote.sourceUrl)}"></label><label class="quote-basis-field" for="quote-share-basis">Economic share basis<select id="quote-share-basis" data-quote="shareBasis"><option value="">Choose the quote’s actual share basis</option><option value="${esc(currentEconomicShareBasis(snapshot,draft))}" ${draft.quote.shareBasis===currentEconomicShareBasis(snapshot,draft)?'selected':''}>${esc(currentEconomicShareBasis(snapshot,draft))}</option><option value="unmatched" ${draft.quote.shareBasis==='unmatched'?'selected':''}>Different or unverified security / split basis</option></select></label></div><p id="quote-comparison" class="micro" role="status"></p></details>`}
function render(){
 releaseSimulation();releaseSimulation=()=>{};if(simulationTimer!==null)clearTimeout(simulationTimer);
 const mode=raw.snapshotMode==='ttm'?'Derived TTM':raw.snapshotMode==='annual-reference'?'Reported FY':'Evidence only';
 app.innerHTML=`<div class="studio-toolbar"><div class="company-control"><span class="company-monogram" aria-hidden="true">${esc(company.ticker.slice(0,1))}</span><div><label for="current-company">Company</label><select id="current-company">${library.companies.map(c=>`<option value="${esc(c.ticker)}" ${c.ticker===company.ticker?'selected':''}>${esc(c.ticker)} · ${esc(c.name)}</option>`).join('')}</select></div></div><div class="baseline-control"><label for="current-snapshot">Financial baseline</label><select id="current-snapshot">${(company.snapshots||[]).map(s=>`<option value="${esc(s.id)}" ${s.id===raw.id?'selected':''}>${esc(s.fiscalLabel||s.snapshotMode+' · '+s.periodEnd)}</option>`).join('')||'<option>Incomplete data</option>'}</select></div><span class="library-status"><i></i> Dated library<br><small>Checked ${esc(library.asOf||'2026-10-17')}</small></span></div><div class="studio-columns"><section class="value-column" aria-label="Live valuation and simulation"><div class="valuation-source-context" role="group" aria-label="Financial period and original filing"><span>${mode} · ${esc(snapshot.periodEnd||'unknown period')}</span><a href="${esc(safeURL(snapshot.sourceUrl))}" target="_blank" rel="noopener" aria-label="Original filing for ${esc(company.ticker)} · ${mode} · ${esc(snapshot.periodEnd||'unknown period')}">Filing ↗</a></div><div id="guided-results" aria-live="polite"></div><div id="simulation-lab"></div><div class="result-context"><span>Provisional claims · illustrative assumptions <a href="#model-limits" id="model-limits-link">Limits ↗</a></span></div></section><section class="assumptions-column" aria-label="Editable assumptions and historical evidence"><div class="assumptions-header"><div><span class="eyebrow">MAKE IT YOURS</span><h2>Assumptions</h2></div><span class="auto-status"><i></i> Updates live</span></div>${baseCasePanel()}${operatingProfilePanel()}<div class="assumption-tabs" role="tablist" aria-label="Assumption categories">${groups.map(g=>`<button id="group-${g.id}" role="tab" aria-selected="${draft.step===g.id}" aria-controls="assumption-editor" data-step="${g.id}" tabindex="${draft.step===g.id?'0':'-1'}">${g.name}</button>`).join('')}</div><div id="assumption-issue" class="assumption-issue" role="note" aria-labelledby="assumption-issue-title" hidden><h3 id="assumption-issue-title">Value withheld</h3><p id="assumption-issue-message"></p></div><div id="assumption-editor" data-group="${draft.step}" class="assumption-editor" role="tabpanel" aria-labelledby="group-${draft.step}">${editorBody()}</div><div class="draft-footer"><span id="guided-save-state"></span><button id="export-draft" class="text-button">Export draft ↓</button></div></section></div><div class="studio-secondary">${quoteForm()}<details id="model-limits" class="model-caveats"><summary>Model limits & unresolved claims</summary><p>Nominal FCFF; ten-year fade; simplified incremental reinvestment. Maintenance replacement, financing, NOLs and award valuation are not separately modeled. All initial assumptions are illustrative. The result does not establish an intrinsic value or expected return.</p><ul>${[...new Set([...(raw.reviewRequired||[]),...(raw.valuationBlockers||[])])].map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>${esc(snapshot.shareBasis)}. Missing claims require judgment; no checkbox can validate them.</p></details></div>${dataOptions()}`;
 $('#current-company').onchange=e=>choose(e.target.value);$('#current-snapshot').onchange=e=>choose(company.ticker,e.target.value);
 $('#model-limits-link').onclick=()=>{$('#model-limits').open=true};
 bindEditor();bindBaseCase();bindQuote();bindImport();refreshQuoteBasis();store();refreshDiagnostics();renderResults(false);worksheetResult();
}
function bindEditor(){
 app.querySelectorAll('[data-step]').forEach(b=>{b.onclick=()=>go(+b.dataset.step);b.onkeydown=e=>{const index=groups.findIndex(g=>g.id===draft.step);let next;if(e.key==='ArrowRight')next=(index+1)%groups.length;else if(e.key==='ArrowLeft')next=(index+groups.length-1)%groups.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=groups.length-1;else return;e.preventDefault();go(groups[next].id);$('#group-'+groups[next].id)?.focus({preventScroll:true})}});
 app.querySelectorAll('[data-assumption]').forEach(el=>el.oninput=()=>updateAssumption(el.dataset.assumption,el.value,el.dataset.scale,false));
 app.querySelectorAll('[data-slider]').forEach(el=>el.oninput=()=>updateAssumption(el.dataset.slider,el.value,el.dataset.scale,true));
 app.querySelectorAll('[data-note]').forEach(el=>el.oninput=()=>{draft.notes[el.dataset.note]=el.value;markDraftEdited(draft,'note:'+el.dataset.note);store()});
 $('#export-draft').onclick=()=>download(`${company.ticker}-valuation-draft.json`,{company,raw,draft});
 if($('#g-cutoff'))$('#g-cutoff').onchange=e=>{draft.cutoff=e.target.value;markDraftEdited(draft,'cutoff');store();render()};
 if($('#g-normalize'))$('#g-normalize').oninput=e=>{draft.normalizationDelta=e.target.value===''?NaN:Number(e.target.value);markDraftEdited(draft,'normalizationDelta');store();renderResults(true)};
 for(const [id,k]of [['g-adjust-reason','adjustmentReason'],['g-adjust-source','adjustmentSource']])if($('#'+id))$('#'+id).oninput=e=>{draft[k]=e.target.value;markDraftEdited(draft,k);store();renderResults(true)};
 app.querySelectorAll('[data-claim]').forEach(el=>el.oninput=()=>{draft.claims={...draft.claims,[el.dataset.claim]:el.value===''?NaN:Number(el.value)/Number(el.dataset.scale)};markDraftEdited(draft,'claims:'+el.dataset.claim);store();renderResults(true)});
 app.querySelectorAll('[data-claim-select]').forEach(el=>el.onchange=()=>{draft.claims={...draft.claims,[el.dataset.claimSelect]:el.value};markDraftEdited(draft,'claims:'+el.dataset.claimSelect);store();refreshQuoteBasis();renderResults(true)});
 if($('#operating-profile'))$('#operating-profile').onchange=e=>{draft.operatingProfile={schemaVersion:1,id:e.target.value};markDraftEdited(draft,'operatingProfile');store();render()};
 if($('#reset-claims'))$('#reset-claims').onclick=()=>{draft.claims=claimsDefaults(snapshot);markDraftEdited(draft,'claims:reset');store();render()};
 app.querySelectorAll('[data-wacc]').forEach(el=>el.oninput=()=>{draft.waccWorksheet[el.dataset.wacc]=el.value===''?null:Number(el.value)/Number(el.dataset.scale);markDraftEdited(draft,'waccWorksheet:'+el.dataset.wacc);try{const v=waccWorksheet(draft.waccWorksheet);draft.assumptions.wacc=v.wacc;const input=$('#g-wacc');if(input)input.value=String(Math.round(v.wacc*10000)/100);const range=$('[data-slider="wacc"]');if(range)range.value=String(v.wacc*100);renderResults(true)}catch{}store();worksheetResult();refreshDiagnostics()});
 if($('#freeze-current'))$('#freeze-current').onclick=()=>{try{download(`${company.ticker}-valuation-${draft.cutoff}.json`,freezeCurrent(snapshot,draft));$('#freeze-status').textContent='Version exported. Your working draft stays editable.'}catch(e){$('#freeze-status').textContent=e.message}};
}
function updateAssumption(k,value,scale,fromRange){
 draft.assumptions[k]=value===''?NaN:Number(value)/Number(scale);markDraftEdited(draft,k);
 const mate=fromRange?$('#g-'+k):$('[data-slider="'+k+'"]');if(mate&&value!=='')mate.value=value;
 store();refreshDiagnostics();renderResults(true);if(k==='wacc')worksheetResult();
}
function bindQuote(){app.querySelectorAll('[data-quote]').forEach(el=>{const update=()=>{draft.quote[el.dataset.quote]=el.dataset.quote==='price'?(el.value===''?null:Number(el.value)):el.value;markDraftEdited(draft,'quote:'+el.dataset.quote);store();renderResults(true)};el.oninput=update;if(el.dataset.quote==='shareBasis')el.onchange=update})}
function worksheetResult(){const el=$('#wacc-output');if(!el)return;try{const v=waccWorksheet(draft.waccWorksheet);el.textContent=`Worksheet: ${pc(v.wacc)} WACC · cost of equity ${pc(v.costOfEquity)} · after-tax debt ${pc(v.afterTaxCostOfDebt)}. Model: ${pc(draft.assumptions.wacc)}.`}catch(e){el.textContent=e.message+' Your scalar WACC remains '+pc(draft.assumptions.wacc)+'.'}}
function refreshDiagnostics(){const a=draft.assumptions;if($('#growth-scale')){let rev=snapshot.revenue;const profile=operatingProfileDefinition(snapshot,draft);for(let y=1;y<=10;y++)rev*=1+(profile?a.terminalGrowth+(a.growth-a.terminalGrowth)*profile.growthWeights[y-1]:a.growth+(a.terminalGrowth-a.growth)*(y-1)/9);$('#growth-scale').innerHTML=`In year 10, this path reaches <b>${num(rev,0)}m ${esc(snapshot.currency)}</b> in revenue. That is <b>${num(rev/snapshot.revenue,1)}×</b> today’s starting business.`}if($('#capital-per-dollar'))$('#capital-per-dollar').textContent=num(1/a.salesCapital,2);if($('#stable-reinvestment'))$('#stable-reinvestment').textContent=pc(a.terminalGrowth/a.terminalROIC)}
function fundingDiagnostics(v){let cumulative=0,trough=0;for(const r of v.rows){cumulative+=r.fcff;trough=Math.min(trough,cumulative)}const negative=v.rows.filter(r=>r.fcff<0).length;return `<div class="funding-diagnostic"><b>${negative} of 10 years have negative FCFF.</b><p>Peak cumulative undiscounted operating cash deficit: ${num(-trough,1)}m USD, before financing, minimum liquidity, coupons and obligations. Cash at the selected bridge reference is ${num(v.claimsBridge?.cash??snapshot.cash,1)}m. This is a funding-stress diagnostic; the model does not forecast issuance, default, recovery or a self-funded turnaround.</p></div><h3>Margin × capital productivity</h3><p class="micro">Illustrative operating stresses, holding your growth, WACC, terminal assumptions and claims treatment constant. These are conditional alternatives, not calibrated forecasts.</p>${table(['Mature EBIT margin','0.8× sales / capital','1.6× sales / capital','2.4× sales / capital'],[.12,.18].map(m=>[pc(m),...[.8,1.6,2.4].map(sc=>{try{return num(calculateCurrent(snapshot,{...draft,assumptions:{...draft.assumptions,targetMargin:m,salesCapital:sc}}).perShare,2)+' USD'}catch{return 'Unavailable'}})]))}`}
function showAssumptionIssue(message=''){
 const issue=$('#assumption-issue');if(!issue)return;
 $('#assumption-issue-message').textContent=message;issue.hidden=!message;
}
function renderResults(edit=false,refreshSimulation=true){
 let v;try{v=calculateCurrent(snapshot,draft)}catch(e){showAssumptionIssue(e.message);releaseSimulation();releaseSimulation=()=>{};if(simulationTimer!==null)clearTimeout(simulationTimer);$('#guided-results').innerHTML=`<div class="valuation-unavailable"><span class="eyebrow">MODEL NEEDS EVIDENCE</span><h2>Value withheld.</h2><p>${esc(e.message)}</p>${currentClaimsEvidence(snapshot).map(x=>`<p class="claim-source"><a href="${esc(safeURL(x.sourceUrl))}" target="_blank" rel="noopener">${esc(x.sourceSection)} · original filing ↗</a></p>`).join('')}<p class="micro">You can still explore the assumptions and history below. These are data and model constraints, not confirmation steps.</p></div>`;$('#simulation-lab').innerHTML='';if($('#quote-comparison'))$('#quote-comparison').textContent='Quote comparison withheld until the current model is valid.';if($('#forecast-detail'))$('#forecast-detail').innerHTML='<p class="error">Resolve the evidence or model issue to show the forecast.</p>';refreshClaimsCalculation(null);return}
 showAssumptionIssue();
 const q=quoteComparison(snapshot,draft,v);
 $('#guided-results').innerHTML=`<div class="live-value"><div><span class="eyebrow">${v.equity<=0?'CONDITIONAL EQUITY FLOOR':'PROVISIONAL BASE CASE'}</span><div class="valuation-number">${num(v.perShare,2)}<span>${esc(snapshot.currency)}<small>/ share</small></span></div></div><div class="live-value-meta"><span>10-year FCFF</span><b>${num(v.enterprise/1000,1)}bn</b><small>operating value</small></div></div>${v.claimsBridge?`<div class="claims-result-note"><b>${esc(v.claimsBridge.capitalBasis==='known-transactions'?'Known-transaction pro forma · incomplete cash bridge':v.claimsBridge.referenceDate+' capital reference')}</b><p>${company.ticker==='AAOI'?'Convertible claim, vendor financing and an intrinsic warrant proxy are included.':'Preferred dilution/dividends, finance leases, NCI and noncurrent investment proxies are included.'} <a href="#group-6" id="open-claims-model">Inspect claims & sensitivities ↗</a></p></div>`:''}${v.equity<=0?`<div class="equity-floor-note"><b>Zero is the model’s limited-liability floor.</b><p>Raw common equity is ${num(v.equity,1)}m ${esc(snapshot.currency)} (${num(v.rawPerShare,2)} / share). This operating path consumes too much capital for its modeled earnings; zero is not evidence that the traded security is worthless.</p></div>`:''}`;
 if($('#open-claims-model'))$('#open-claims-model').onclick=e=>{e.preventDefault();go(6)};
 refreshClaimsCalculation(v);
 if($('#quote-comparison'))$('#quote-comparison').textContent=q.status==='ready'?`${num(q.price,2)} ${snapshot.currency} on ${q.date} · value-to-price gap ${pc(q.gap)}. Not an expected return.`:q.message;
 if($('#forecast-detail'))$('#forecast-detail').innerHTML=`<div class="detail-metrics"><div><span>Terminal PV share</span><b>${v.enterprise>0?pc(v.terminalShare):'Not meaningful'}</b></div><div><span>Common equity</span><b>${num(v.equity,0)}m</b></div></div><p class="micro">${v.enterprise>0?'A high terminal share means value depends heavily on mature growth, returns and discount rate.':'Terminal-value share is not meaningful when operating enterprise value is nonpositive.'}</p>${company.ticker==='AAOI'?fundingDiagnostics(v):''}${v.operatingProfile?`<details open><summary>Staged annual path · applied to every scenario</summary>${table(['Year','Growth','EBIT margin','Sales / capital'],v.operatingProfile.annualPath.map((r,i)=>[i+1,pc(r.growth),pc(r.margin),num(r.salesCapital,3)+'×']))}<p class="micro">Capital intensity in year 10 = (1 + stable growth) × mature margin × (1 − tax) / terminal ROIC. This matches the terminal reinvestment timing. The profile is an analyst assumption; default, recovery and financing are not modeled.</p></details>`:''}${table(['Year','Revenue','EBIT','Reinvestment','FCFF'],v.rows.map(r=>[r.year,num(r.revenue),num(r.ebit),num(r.reinvestment),num(r.fcff)]))}<h3>Illustrative stresses</h3><div class="stress-cases">${[['Downside',-.03,-.03,.01],['Base',0,0,0],['Upside',.03,.03,-.01]].map(([label,g,m,w])=>{let amount;try{amount=calculateCurrent(snapshot,{...draft,assumptions:{...draft.assumptions,growth:draft.assumptions.growth+g,targetMargin:Math.max(0,draft.assumptions.targetMargin+m),wacc:draft.assumptions.wacc+w}}).perShare}catch{}return `<div><span>${label}</span><b>${num(amount,2)}</b></div>`}).join('')}</div><p class="micro">Growth and margin ±3pp; WACC ∓1pp. These are stress tests, not estimated probabilities.</p>`;
 if(simulationTimer!==null)clearTimeout(simulationTimer);
 if(!refreshSimulation)return;
 const mount=()=>{releaseSimulation();const simulationDraft=draft;releaseSimulation=mountSimulation($('#simulation-lab'),snapshot,draft,{animateChange:edit&&!firstMount,onConfigChange:config=>{if(draft!==simulationDraft)return;draft.simulationConfig=config;markDraftEdited(draft,'simulationConfig');store();}});firstMount=false;simulationTimer=null};
 if(edit)simulationTimer=setTimeout(mount,120);else mount();
}
function go(step){
 const previous=draft.step;draft.step=Math.max(0,Math.min(7,step));store();
 // Only replace the editor: the visible simulation and user-selected marker stay put.
 const editor=$('#assumption-editor');editor.innerHTML=editorBody();editor.setAttribute?.('aria-labelledby','group-'+draft.step);editor.setAttribute?.('data-group',String(draft.step));
 app.querySelectorAll('[data-step]').forEach(b=>{b.setAttribute?.('aria-selected',String(+b.dataset.step===draft.step));b.setAttribute?.('tabindex',+b.dataset.step===draft.step?'0':'-1')});
 bindEditor();refreshDiagnostics();worksheetResult();if(draft.step===7||draft.step===6)renderResults(false,false);enterPanel(editor,step>=previous?1:-1);$('#guided-step-title')?.focus({preventScroll:true});$('#group-'+draft.step)?.scrollIntoView?.({block:'nearest',inline:'nearest',behavior:reducedMotion()?'auto':'smooth'});
}
function dataOptions(){return `<details id="current-data-options" class="data-options"><summary>Data coverage & imports <span>14 companies · API disconnected</span></summary><p>Dated issuer/SEC financials, checked as of ${esc(library.asOf)}. No filing or quote refresh runs automatically. Unknown values stay missing; ADR currency conversion and specialist models require verified mappings.</p><p><a href="./data/provider-research.html" target="_blank" rel="noopener">Provider feasibility & rights ↗</a> · <a href="https://www.sec.gov/search-filings/edgar-application-programming-interfaces" target="_blank" rel="noopener">SEC data documentation ↗</a></p><p class="micro">SEC data require server-side caching and audited mappings. No API account, key or backend is connected.</p><h3>Import a sourced company</h3><p class="micro">Local JSON only. Amounts/shares in millions, dated FY/TTM flows and explicit share basis. Imports are not uploaded; export to keep a copy.</p><label for="current-import-file">Company JSON</label><input id="current-import-file" type="file" accept=".json"><button id="current-template" class="quiet">Download schema ↓</button><p id="current-import-status" role="status"></p></details>`}
function bindImport(){
 $('#current-template').onclick=()=>download('current-company-schema.json',{ticker:'REPLACE',name:'Reviewed operating company',modelType:'operating-fcff',sector:'Nonfinancial operating sector',currency:'USD',currentSnapshotId:'REPLACE-FY',snapshots:[{id:'REPLACE-FY',snapshotMode:'annual-reference',periodEnd:'2025-12-31',filingDate:'2026-03-01',sourceUrl:'https://www.sec.gov/Archives/REPLACE',currency:'USD',revenue:null,EBIT:null,cash:null,debt:null,shares:null,shareBasis:'Specify economic common shares and split convention',sharesAsOf:'2025-12-31',valuationBlockers:['Cash, debt, leases, claims and dilution need judgment.'],backtestEligible:false}]});
 $('#current-import-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2e6)throw Error('Use a JSON file smaller than 2 MB.');const c=JSON.parse(await f.text());if(typeof c.ticker!=='string'||typeof c.name!=='string'||!Array.isArray(c.snapshots)||!c.snapshots.length)throw Error('Expected ticker, name and a nonempty snapshots array.');if(!/^[A-Z0-9.-]{1,12}$/.test(c.ticker)||c.snapshots.some(s=>!s||typeof s.id!=='string')||new Set(c.snapshots.map(s=>s.id)).size!==c.snapshots.length)throw Error('Use a valid ticker and unique string snapshot IDs.');library.companies=library.companies.filter(x=>x.ticker!==c.ticker);c.researchImported=true;library.companies.push(c);choose(c.ticker,c.currentSnapshotId);$('#current-data-options').open=true;$('#current-import-status').textContent='Imported on this device. Missing facts and model constraints remain visible.'}catch(e){$('#current-import-status').textContent=e.message}};
}
try{
 const l=await fetch('./data/current-universe.json');if(!l.ok)throw Error('The sourced company library could not be loaded. Historical cases remain available.');library=await l.json();
 await Promise.all([fetchBaseCases({fetcher:fetch}).then(v=>{baseCases=v}),Promise.all([['./data/company-history.json',v=>historyData=v],['./data/current-market-references.json',v=>marketReferences=v]].map(async([path,set])=>{try{const r=await fetch(path);if(r.ok)set(await r.json())}catch{}}))]);
 if(!Array.isArray(library.companies)||!library.companies.length)throw Error('No company records available.');let selection;try{selection=JSON.parse(localStorage.getItem('valuation-lab-guided-selection')||'null')}catch{}
 choose(selection?.ticker||'AAPL',selection?.id);
}catch(e){app.innerHTML=`<div class="error">${esc(e.message)}</div>`}
